import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // ---- Create container -------------------------------------------------
  const container = new Group();

  // ---- Geometry & Material -----------------------------------------------
  // Aspect ratio derived from atlas source rect (512 / 320 = 1.6)
  const aspect = 512 / 320;
  const width = 1.6; // arbitrary scene units respecting aspect
  const height = width / aspect;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff });
  const mesh = new Mesh(geometry, material);
  container.add(mesh);

  // ---- Load texture -------------------------------------------------------
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // ---- Hover animation (rise‑in) -----------------------------------------
  const hoverTL = gsap.timeline({ paused: true });
  hoverTL.to(
    mesh.position,
    { y: '+=0.15', duration: 0.2, ease: 'power3.out' },
  );

  // ---- Click animation (press‑down) ---------------------------------------
  const pressTL = gsap.timeline({ paused: true });
  pressTL.to(
    mesh.scale,
    { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(1.7)' },
  );

  // ---- User event handlers ------------------------------------------------
  const handlers = {
    hover: (state) => {
      if (state === 'enter') hoverTL.play();
      else if (state === 'leave') hoverTL.reverse();
    },
    click: () => {
      pressTL.restart();
      ctx.emit('hub-pricing.select', {});
    },
  };

  // ---- Apply cinematic primitives -----------------------------------------
  const primitiveRefs = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const prim of primitives) {
    const instance = ctx.primitives[prim.name](container, prim.params ?? {});
    if (instance) primitiveRefs.push(instance);
  }

  // ---- Cleanup ------------------------------------------------------------
  const cleanup = () => {
    geometry.dispose();
    material.dispose();
    hoverTL.kill();
    pressTL.kill();
    for (const inst of primitiveRefs) {
      if (typeof inst.cleanup === 'function') inst.cleanup();
    }
  };

  // ---- Attach to userData -------------------------------------------------
  container.userData = {
    handlers,
    cleanup,
  };

  return container;
}
